insert into public.posts (author, board_id, type, title, body, prompt, task, tool, model_version, minutes_before, minutes_after, what_wrong, data_class, tags, status, pinned, is_sample, tool_key, knowledge_sources) values
 (null,'townhall','MEETING','This week''s town meeting: the admin task you''ve handed to AI','Reply with one admin task you now do with AI, what it saves, what data went in, and what still needs a human.','','','','',null,null,'','',array['meeting','admin'],'published',true,true,'','[]'),
 (null,'townhall','MOTION','Motion: every build post must name the model or version','AI tools change every few months. Naming the model lets readers judge whether advice still applies. Vote For or Against.','','','','',null,null,'','',array['site-rules'],'published',false,true,'','[]'),
 (null,'exams-timetabling','WORKFLOW','Exam board papers: 3 hours down to 45 minutes','Copilot drafts the narrative sections from the agreed board template. The officer still checks every figure against the records system.','Using only the attached anonymised summary tables, draft the module commentary in the house template. Do not interpret marks. Flag any table that looks incomplete.','Draft exam board commentary from anonymised summary tables','Microsoft 365 Copilot (institution licence)','Copilot, Nov 2026',180,45,'First drafts described trends the tables did not show. The "do not interpret marks" line fixed it.','internal',array['copilot','exam-boards','registry'],'published',false,true,'copilot','[]'),
 (null,'student-support','AGENT','Copilot Studio agent that answers questions about academic regulations','Knowledge source: the published regulations pages only. No actions. It refuses anything about an individual case and points to the registry inbox instead.','You answer questions about the published academic regulations. Quote the section you used. If a question is about a specific student or case, say you cannot help and suggest contacting the registry team.','Answer staff questions about academic regulations','Copilot Studio','Copilot Studio, Oct 2026',20,3,'Early versions answered from general knowledge. Restricting it to the regulations pages and requiring a quoted section stopped that.','none',array['copilot-studio','regulations','agents'],'published',false,true,'copilot-studio','[{"kind":"website","note":"The published academic regulations pages only"},{"kind":"instructions-only","note":"No actions or connectors"}]'),
 (null,'marking-feedback','WORKFLOW','Feedback bank from a marking rubric','The marker writes their own comments; AI only suggests wording from the rubric bands. No student work goes in.','For each band of this rubric, write three short feedback comments a marker could adapt. Plain English, second person, no grades.','Turn a marking rubric into a bank of feedback comments','Gemini (institution account)','Gemini, Nov 2026',120,30,'Comments were too generic at first. Giving it two real anonymised comments as style examples helped.','none',array['gemini','feedback','marking'],'published',false,true,'gemini','[]'),
 (null,'policy-governance','FAIL','Copilot summarised a 40-page procurement tender and missed the penalty clause','Summaries are a map, not the territory. Now I ask for every clause with a number or deadline, then check that list against the document.','','Summarise a supplier tender before a panel meeting','Microsoft 365 Copilot in Word','Copilot, Oct 2026',240,5,'A fluent, complete-looking summary skipped a late-delivery penalty in an appendix table.','internal',array['copilot','procurement','summarising'],'published',false,true,'copilot','[]'),
 (null,'admissions','WORKFLOW','Course page to plain-English FAQ for applicants','Every answer is checked against the live course page before publishing.','Using only the course page below, write 10 questions applicants ask and short answers. If the page does not answer something, write "Check with admissions" instead of guessing.','Create applicant FAQs from published course pages','ChatGPT Edu','ChatGPT Edu, Nov 2026',90,25,'It guessed entry requirements that were not on the page. The "check with admissions" rule fixed it.','none',array['chatgpt-edu','admissions','applicants'],'published',false,true,'chatgpt-edu','[]'),
 (null,'policy-governance','QUESTION','How are other universities checking AI-generated content before it goes to students?','We have a review step but it is inconsistent across departments. What do your checks look like in practice?','','','','',null,null,'','',array['checking-output','policy','quality'],'published',false,true,'','[]');
